"""Bounded halting probe: halting is confirmable, non-halting is not."""
from __future__ import annotations
from typing import Callable, Optional, Tuple


def bounded_halt_probe(step: Callable[[int], Optional[int]], start: int,
                       budget: int) -> Tuple[str, Optional[int]]:
    state = start
    for used in range(budget):
        nxt = step(state)
        if nxt is None:
            return ("halted", used + 1)
        state = nxt
    return ("unknown", None)


def collatz_step(n: int) -> Optional[int]:
    if n == 1:
        return None
    return n // 2 if n % 2 == 0 else 3 * n + 1


if __name__ == "__main__":
    for start in (6, 27, 97):
        print(start, bounded_halt_probe(collatz_step, start, 1000))
    # A divergent program is forever "unknown": non-halting is never certified.
    print("counter", bounded_halt_probe(lambda s: s + 1, 0, 10_000))

