from typing import Callable, Optional, Tuple


def bounded_halt_probe(step: Callable[[int], Optional[int]], start: int,
                       budget: int) -> Tuple[str, Optional[int]]:
    """Semi-decide halting: simulate up to `budget` transitions.

    Returns ("halted", steps) on termination, else ("unknown", None).
    Never returns a non-halting certificate -- that is impossible in finite
    time. Time O(budget), space O(1) beyond the state.
    """
    state = start
    for used in range(budget):
        nxt = step(state)
        if nxt is None:
            return ("halted", used + 1)
        state = nxt
    return ("unknown", None)

