from __future__ import annotations
from typing import Callable, Sequence


def diagonalize(listing: Sequence[Callable[[int], bool]], n: int) -> bool:
    """Value at n of the diagonal function d(n) = not f_n(n).

    For any listing f_0, f_1, ... of Boolean functions, d differs from f_n at
    input n, hence d is not in the listing. Time O(cost(f_n)).
    """
    if n < len(listing):
        return not listing[n](n)
    return True
